#!/usr/bin/env python3
"""Writes outputs/branching_replay/protocol_freeze.json BEFORE any branch result exists (refuses to overwrite). Run: python3 eval/branching_freeze.py"""
import json, sys, time, hashlib
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent; sys.path.insert(0, str(ROOT / "eval")); D = ROOT / "outputs/branching_replay"; F = D / "protocol_freeze.json"
if F.exists(): sys.exit("freeze exists")
if (D / "results").exists() and any((D / "results").glob("worker*.json")): sys.exit("results exist before freeze")
sh = lambda p: hashlib.sha256((ROOT / p).read_bytes()).hexdigest()
import closed_loop_pilot as P, branching_replay as BR, branching_metrics as BM, decision_utility_lib as L
rep = json.loads((D / "integration_report.json").read_text()); assert rep["verdict"] == "PASS" and rep["n_gates"] == 8
for f, h in rep["code_sha256"].items(): assert sh(f) == h, f
poses = P.pilot_poses(); files = ["eval/branching_replay.py", "eval/branching_metrics.py", "eval/test_branching_replay.py", "eval/branching_replay_analysis.py", "eval/branching_freeze.py", "eval/closed_loop_pilot.py", "eval/decision_utility_lib.py", "eval/wm2_run.py", "eval/wm2_models.py", "eval/wm3b_model.py",
         "data/wm1_sim.py", "control/safety_limits.py", "control/action_adapter.py", "sim/lab_env.py", "sim/lab_scene.py", "outputs/xsweep/xsweep_config.json", "outputs/closed_loop_pilot/protocol_freeze.json", "outputs/branching_replay/integration_report.json", "outputs/wm3/models/wm3b.pt", "outputs/decision_utility/protocol_freeze.json"]
for k, d in P.CK.items(): files += [f"outputs/checkpoints/{d}/last/model.safetensors", f"outputs/checkpoints/{d}/last/config.json", f"outputs/checkpoints/{d}/last/norm_contract.json", f"outputs/checkpoints/{d}/last/policy_preprocessor_step_3_normalizer_processor.safetensors", f"outputs/checkpoints/{d}/last/policy_postprocessor_step_0_unnormalizer_processor.safetensors"]
fz = dict(name="Offline branching replay - protocol freeze", frozen_at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), branch_results_exist_at_freeze=False, label="DEVELOPMENT offline branching replay; privileged oracle observer; simulation only; short-horizon candidate ranking; not closed-loop success evidence",
          poses=poses, poses_sha256=hashlib.sha256(json.dumps(poses, sort_keys=True).encode()).hexdigest(), decision_states=BR.STATES, j2_states=BR.J2_STATES, candidates=P.CK, default_candidate="c0_s0", n_expected=dict(poses=24, states=216, branches=648),
          procedure="A0 (default c0_s0) replayed per pose; at each decision state: snapshot (mj_copyData + prev_ctrl + time), generate 3 candidates from the same observation, sequential clip->slew from last executed target, frozen WM3-B + frozen J20 prediction BEFORE branching, then each candidate executed from the restored snapshot; realised J20 on executed rows t..t+20; replay continues with the default candidate; realised outcomes never select actions.",
          J20="frozen J (eval/decision_utility_lib.py: dxy + |z-0.384| + 0.05*palm_any(>0.01N) + 0.05*(rise<0.05 within window)) at row t+20 for prediction; identical formula on executed rows for the label", constants=dict(TRAY=L.TRAY.tolist(), Z_TRAY=L.Z_TRAY, PALM_THR=L.PALM_THR, LIFT_M=L.LIFT_M, W_PALM=L.W_PALM, W_LIFT=L.W_LIFT),
          J2="prediction: L.rollout of 2 WM3-B blocks over [candidate executed chunk, 20 steps holding the last executed 16-D target (no future observation)]; label: realised J (same formula) over the 41 rows t..t+40 of [candidate, hold]; states t<=160 only; evaluated only if budget allows after the primary phase of the same worker; NOT closed-loop continuation; continuation is hold, not a policy",
          metrics=dict(pair_threshold=BM.THR_PAIR, tie_tol=BM.TOL, tie_break="sha1(pose|vid|tie), vid=candidate index [c0_s0,c0_s1,c0_s2]", gating_tau=BM.TAU, fallback="c0_s0", bootstrap="resample the 24 poses (never states or branches), 10000, seed 0, 95% percentile", pairwise="accuracy over candidate pairs with |dJ_true|>=0.01, predicted ties score 0.5, pooled ratio estimator with pose bootstrap",
                       regret="J_true(selected) - min_k J_true(k); normalized by (median - min) when > 1e-9; comparators: default (k=0), uniform-random (exact expectation), margin-gated (tau=0.01, fallback default); headroom = J_true(default) - min_k J_true(k); has_headroom if headroom >= 0.01", phases="approach/grasp/carry/place from privileged state of the A0 replay (phase_of in closed_loop_pilot)"),
          stop_rules=["cap 0.40 process CPU-h for the whole experiment (ledger) -> PARTIAL, never raised", "any illegal/non-finite chunk or applied-ctrl mismatch -> BLOCKED", "frozen file hash change", "snapshot determinism or action semantics failure -> STOP (integration gates)", "oracle headroom < 0.01 in > 80% of decision states -> report and stop ranking research under this protocol", "J2 not completed within budget -> NOT_EVALUABLE/PARTIAL (primary unaffected)"],
          compute=dict(cap_total_s=BR.CAP_TOTAL_S, ledger_used_at_freeze_s=BR.ledger_used(), workers=4, per_worker_cap_s="(cap - ledger_used - 30)/4"), files_sha256={f: sh(f) for f in files})
P.atomic_json(F, fz); print(hashlib.sha256(F.read_bytes()).hexdigest(), fz["frozen_at"], len(files), "files; ledger", fz["compute"]["ledger_used_at_freeze_s"])
